package com.dndmaster.aigamemaster;
import static org.junit.jupiter.api.Assertions.*;import com.dndmaster.aigamemaster.api.AiStreamingResponseService;import com.dndmaster.aigamemaster.infrastructure.ai.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.ai.chat.messages.AssistantMessage;import org.springframework.ai.chat.model.*;import org.springframework.ai.chat.prompt.Prompt;import reactor.core.publisher.Flux;
class StreamingResponseIntegrationTest{
 @Test void interruptedStreamIsNotCompletedAndExplicitSameKeyRetryIsCachedWithoutDuplicateProviderCall(){InterruptOnceModel model=new InterruptOnceModel();List<String> logs=new ArrayList<>();AiStreamingResponseService service=new AiStreamingResponseService(new SpringAiChatAdapter(model,3,new SafeAiAuditLogger(logs::add)));assertThrows(RuntimeException.class,()->service.stream("stream-1","grounded private-map-secret").collectList().block());List<String> retry=service.stream("stream-1","grounded private-map-secret").collectList().block();List<String> duplicate=service.stream("stream-1","grounded private-map-secret").collectList().block();assertEquals(List.of("whole ","answer"),retry);assertEquals(retry,duplicate);assertEquals(2,model.calls);assertTrue(logs.stream().noneMatch(l->l.contains("private-map-secret")||l.contains("partial")));}
 @Test void sameStreamOperationRejectsDifferentPrompt(){SpringAiChatAdapter adapter=new SpringAiChatAdapter(new InterruptOnceModel(),1,new SafeAiAuditLogger(s->{}));adapter.stream("same","one");assertThrows(AiOperationConflictException.class,()->adapter.stream("same","two"));}
 private static final class InterruptOnceModel implements ChatModel{int calls;public ChatResponse call(Prompt prompt){throw new UnsupportedOperationException();}@Override public Flux<ChatResponse> stream(Prompt prompt){calls++;if(calls==1)return Flux.concat(Flux.just(response("partial")),Flux.error(new ProviderTimeoutException(new RuntimeException("stream interrupted"))));return Flux.just(response("whole "),response("answer"));}}
 private static ChatResponse response(String text){return new ChatResponse(List.of(new Generation(new AssistantMessage(text))));}
}
